import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Day 8: Linux Kernel Customization & Device Tree Overlays in Yocto","description":"","frontmatter":{},"headers":[],"relativePath":"day8-kernel-customization-and-device-trees.md","filePath":"day8-kernel-customization-and-device-trees.md"}'),t={name:"day8-kernel-customization-and-device-trees.md"};function p(l,e,r,o,c,d){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="day-8-linux-kernel-customization-device-tree-overlays-in-yocto" tabindex="-1">Day 8: Linux Kernel Customization &amp; Device Tree Overlays in Yocto <a class="header-anchor" href="#day-8-linux-kernel-customization-device-tree-overlays-in-yocto" aria-label="Permalink to &quot;Day 8: Linux Kernel Customization &amp; Device Tree Overlays in Yocto&quot;">​</a></h1><p>This module covers modifying the Linux Kernel configuration inside Yocto using <code>menuconfig</code>, generating <code>.cfg</code> configuration fragments, customizing device tree sources (<code>.dts</code>/<code>.dtsi</code>), and writing <code>device-tree.bbappend</code> files.</p><hr><h2 id="_1-modifying-the-linux-kernel-configuration-menuconfig" tabindex="-1">1. Modifying the Linux Kernel Configuration (<code>menuconfig</code>) <a class="header-anchor" href="#_1-modifying-the-linux-kernel-configuration-menuconfig" aria-label="Permalink to &quot;1. Modifying the Linux Kernel Configuration (\`menuconfig\`)&quot;">​</a></h2><p>Yocto builds the kernel via the <code>virtual/kernel</code> target recipe. Instead of manually editing <code>.config</code> inside <code>tmp/work/</code>, use BitBake tasks to configure the kernel safely.</p><h3 id="step-1-launch-kernel-menuconfig" tabindex="-1">Step 1: Launch Kernel Menuconfig <a class="header-anchor" href="#step-1-launch-kernel-menuconfig" aria-label="Permalink to &quot;Step 1: Launch Kernel Menuconfig&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> menuconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtual/kernel</span></span></code></pre></div><p><em>This opens the standard <code>ncurses</code> kernel configuration graphical menu inside your terminal window.</em></p><h3 id="step-2-enable-or-disable-drivers" tabindex="-1">Step 2: Enable or Disable Drivers <a class="header-anchor" href="#step-2-enable-or-disable-drivers" aria-label="Permalink to &quot;Step 2: Enable or Disable Drivers&quot;">​</a></h3><p>Navigate through kernel subsystems (e.g., enable CAN bus drivers, SPI controllers, USB Wi-Fi dongle support, or PREEMPT_RT patch settings). Save and exit <code>menuconfig</code>.</p><h3 id="step-3-diff-and-generate-a-configuration-fragment-cfg" tabindex="-1">Step 3: Diff and Generate a Configuration Fragment (<code>.cfg</code>) <a class="header-anchor" href="#step-3-diff-and-generate-a-configuration-fragment-cfg" aria-label="Permalink to &quot;Step 3: Diff and Generate a Configuration Fragment (\`.cfg\`)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diffconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtual/kernel</span></span></code></pre></div><p><em>Outputs a minimal config fragment file named <code>fragment.cfg</code> containing <strong>only the lines modified</strong>!</em></p><hr><h2 id="_2-integrating-kernel-fragments-via-bbappend" tabindex="-1">2. Integrating Kernel Fragments via <code>.bbappend</code> <a class="header-anchor" href="#_2-integrating-kernel-fragments-via-bbappend" aria-label="Permalink to &quot;2. Integrating Kernel Fragments via \`.bbappend\`&quot;">​</a></h2><p>Create a recipe append file in your custom layer (e.g., <code>meta-custom/recipes-kernel/linux/linux-yocto_%.bbappend</code>):</p><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILESEXTRAPATHS:prepend := &quot;\${THISDIR}/files:&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Add custom config fragment to kernel build</span></span>
<span class="line"><span>SRC_URI:append = &quot; file://wifi-drivers.cfg&quot;</span></span></code></pre></div><h3 id="example-wifi-drivers-cfg-fragment" tabindex="-1">Example <code>wifi-drivers.cfg</code> Fragment <a class="header-anchor" href="#example-wifi-drivers-cfg-fragment" aria-label="Permalink to &quot;Example \`wifi-drivers.cfg\` Fragment&quot;">​</a></h3><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_CFG80211</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=m</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_MAC80211</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=m</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_ATH_CARDS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=m</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CONFIG_ATH9K_HTC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=m</span></span></code></pre></div><p>Rebuild the kernel image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bitbake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> virtual/kernel</span></span></code></pre></div><hr><h2 id="_3-device-tree-customization-in-yocto" tabindex="-1">3. Device Tree Customization in Yocto <a class="header-anchor" href="#_3-device-tree-customization-in-yocto" aria-label="Permalink to &quot;3. Device Tree Customization in Yocto&quot;">​</a></h2><p>The <strong>Device Tree</strong> describes the hardware layout (memory address ranges, interrupts, clocks, pin multiplexing) to the Linux kernel at boot time.</p><h3 id="where-device-trees-live-in-yocto" tabindex="-1">Where Device Trees Live in Yocto <a class="header-anchor" href="#where-device-trees-live-in-yocto" aria-label="Permalink to &quot;Where Device Trees Live in Yocto&quot;">​</a></h3><ul><li>Kernel source device trees: <code>arch/arm/boot/dts/</code> or <code>arch/arm64/boot/dts/</code>.</li><li>BSP layer device tree recipes: <code>recipes-bsp/device-tree/device-tree.bb</code>.</li></ul><hr><h2 id="_4-writing-a-device-tree-bbappend-override" tabindex="-1">4. Writing a <code>device-tree.bbappend</code> Override <a class="header-anchor" href="#_4-writing-a-device-tree-bbappend-override" aria-label="Permalink to &quot;4. Writing a \`device-tree.bbappend\` Override&quot;">​</a></h2><p>To add custom peripheral nodes (e.g., I2C temperature sensors, SPI displays, or generic UIO memory maps) without modifying standard kernel tree files, append to the <code>device-tree</code> recipe.</p><h3 id="structure-of-meta-custom-recipes-bsp-device-tree-device-tree-bbappend" tabindex="-1">Structure of <code>meta-custom/recipes-bsp/device-tree/device-tree.bbappend</code> <a class="header-anchor" href="#structure-of-meta-custom-recipes-bsp-device-tree-device-tree-bbappend" aria-label="Permalink to &quot;Structure of \`meta-custom/recipes-bsp/device-tree/device-tree.bbappend\`&quot;">​</a></h3><div class="language-bitbake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bitbake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FILESEXTRAPATHS:prepend := &quot;\${THISDIR}/files:&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SRC_URI:append = &quot; file://system-user.dtsi&quot;</span></span></code></pre></div><h3 id="example-custom-device-tree-include-system-user-dtsi" tabindex="-1">Example Custom Device Tree Include (<code>system-user.dtsi</code>) <a class="header-anchor" href="#example-custom-device-tree-include-system-user-dtsi" aria-label="Permalink to &quot;Example Custom Device Tree Include (\`system-user.dtsi\`)&quot;">​</a></h3><div class="language-dts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/include/ &quot;system-top.dts&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/ {</span></span>
<span class="line"><span>    chosen {</span></span>
<span class="line"><span>        bootargs = &quot;console=ttyPS0,115200 earlycon root=/dev/mmcblk0p2 rw rootwait&quot;;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    reserved-memory {</span></span>
<span class="line"><span>        #address-cells = &lt;1&gt;;</span></span>
<span class="line"><span>        #size-cells = &lt;1&gt;;</span></span>
<span class="line"><span>        ranges;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        /* Reserve 16MB RAM for shared memory DMA */</span></span>
<span class="line"><span>        dma_reserved: buffer@3e000000 {</span></span>
<span class="line"><span>            compatible = &quot;shared-dma-pool&quot;;</span></span>
<span class="line"><span>            reg = &lt;0x3e000000 0x01000000&gt;;</span></span>
<span class="line"><span>            no-map;</span></span>
<span class="line"><span>        };</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/* Enable I2C-1 controller and add TMP102 temperature sensor node */</span></span>
<span class="line"><span>&amp;i2c1 {</span></span>
<span class="line"><span>    status = &quot;okay&quot;;</span></span>
<span class="line"><span>    clock-frequency = &lt;100000&gt;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    temp_sensor: temp-sensor@48 {</span></span>
<span class="line"><span>        compatible = &quot;ti,tmp102&quot;;</span></span>
<span class="line"><span>        reg = &lt;0x48&gt;;</span></span>
<span class="line"><span>    };</span></span>
<span class="line"><span>};</span></span></code></pre></div><hr><h2 id="_5-compiling-device-trees-manually-with-dtc" tabindex="-1">5. Compiling Device Trees Manually with <code>dtc</code> <a class="header-anchor" href="#_5-compiling-device-trees-manually-with-dtc" aria-label="Permalink to &quot;5. Compiling Device Trees Manually with \`dtc\`&quot;">​</a></h2><p>To inspect or debug compiled Device Tree Blobs (<code>.dtb</code>) output by Yocto:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Decompile DTB binary back to DTS text</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decompiled.dts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> output/images/system.dtb</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Compile modified DTS directly to DTB</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dtc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -O</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dtb</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> custom_system.dtb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> decompiled.dts</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">RUNTIME DEVICE TREE INSPECTION</p><p>Boot your target hardware and inspect the running Device Tree directly in Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/device-tree/model</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/firmware/devicetree/base/i2c@40003000/status</span></span></code></pre></div></div>`,38)])])}const g=s(t,[["render",p]]);export{u as __pageData,g as default};
